import CatalogMenu from "../../features/CatalogMenu/CatalogMenu";
import CatalogItems from "../../features/CatalogItems/CatalogItems";


const CatalogPage: FC = () => {
    return (
        <>
            <CatalogMenu />
            <CatalogItems />
            {createModal && <CreateModal onClose={handleCloseCreateModal} onCreate={createDestination} />}
            {updateModal && selectedDestination && (
                <UpdateModal
                    onClose={handleCloseUpdateModal}
                    onUpdate={updateDestination}
                    destination={selectedDestination}
                />
            )}
        </>
    );
};

export default CatalogPage;
